insertion_refs_file:
# Per-wire marker references read off Media/IBVS/poses/ (848x480 camera pixels; centre x, y and side length of the marker).
# pre = marker as seen at the pre-insertion pose, insert = marker as seen with the plug at the socket entrance.
# plug_x = where the middle of the two fingertips is in the image when the goal was recorded (the plug sits a little differently in the grasp every time; the servo moves the insertion goal by the difference)
# nudge_px moves the insertion target in the image (x right, y down) to fine-tune where the gripper ends up; marker_side_m is the printed size.
marker_side_m: 0.030
